// Adaptive Sorting Algorithm Implementation
// This program implements a sorting algorithm that can be evolved to adapt to different data patterns

use std::cmp::Ordering;

// EVOLVE-BLOCK-START
// HYPOTHESIS-1: Switching from naive quicksort to an introsort variant with insertion cutoff will improve performance_score by avoiding worst-case recursion and reducing overhead on small partitions.
// MECHANISM-1: Depth-limited quicksort falls back to heapsort on bad pivots; insertion sort is faster for tiny ranges due to low constant factors.
// EXPECT-1: performance_score > 0.985
// RESULT-1: CONFIRMED (actual=0.9975215758480365)
// HYPOTHESIS-2: Replacing O(n^2) nearly-sorted detection with an O(n) adjacent-disorder check will improve avg_time while preserving adaptability_score.
// MECHANISM-2: Linear scan early-exits for disordered inputs and triggers insertion sort for low-disorder inputs, reducing work and variance.
// EXPECT-2: avg_time < 0.0020
// RESULT-2: CONFIRMED (actual=0.00024845819999999997)

const INSERTION_THRESHOLD: usize = 24;

pub fn adaptive_sort<T: Ord + Clone>(arr: &mut [T]) {
    let len = arr.len();
    if len <= 1 { return; }
    if len <= INSERTION_THRESHOLD { insertion_sort(arr); return; }

    // O(n) nearly-sorted check via adjacent inversions
    let mut disorder = 0usize;
    for i in 0..len - 1 {
        if arr[i] > arr[i + 1] { disorder += 1; }
    }
    if disorder <= len / 8 {
        insertion_sort(arr);
        return;
    }

    let max_depth = (2.0 * (len as f64).log2()) as usize;
    introsort(arr, 0, len - 1, max_depth);
}

fn introsort<T: Ord + Clone>(arr: &mut [T], low: usize, high: usize, depth: usize) {
    if high <= low { return; }
    let size = high - low + 1;
    if size <= INSERTION_THRESHOLD {
        insertion_sort_range(arr, low, high);
        return;
    }
    if depth == 0 {
        heapsort_range(arr, low, high);
        return;
    }
    let p = partition_mo3(arr, low, high);
    if p > 0 { introsort(arr, low, p.saturating_sub(1), depth - 1); }
    introsort(arr, p + 1, high, depth - 1);
}

fn partition_mo3<T: Ord + Clone>(arr: &mut [T], low: usize, high: usize) -> usize {
    let mid = low + (high - low) / 2;
    // median-of-three ordering
    if arr[low] > arr[mid] { arr.swap(low, mid); }
    if arr[low] > arr[high] { arr.swap(low, high); }
    if arr[mid] > arr[high] { arr.swap(mid, high); }

    // place pivot at high-1
    arr.swap(mid, high - 1);
    if high - low < 2 { return high - 1; }

    let pivot = arr[high - 1].clone();
    let mut i = low + 1;
    let mut j = high - 2;
    loop {
        while arr[i] < pivot { i += 1; }
        while j > low && arr[j] > pivot { j -= 1; }
        if i >= j { break; }
        arr.swap(i, j);
        i += 1;
        j -= 1;
    }
    arr.swap(i, high - 1);
    i
}

fn insertion_sort<T: Ord>(arr: &mut [T]) {
    for i in 1..arr.len() {
        let mut j = i;
        while j > 0 && arr[j - 1] > arr[j] {
            arr.swap(j, j - 1);
            j -= 1;
        }
    }
}

fn insertion_sort_range<T: Ord>(arr: &mut [T], low: usize, high: usize) {
    for i in (low + 1)..=high {
        let mut j = i;
        while j > low && arr[j - 1] > arr[j] {
            arr.swap(j, j - 1);
            j -= 1;
        }
    }
}

fn heapsort_range<T: Ord>(arr: &mut [T], low: usize, high: usize) {
    let n = high - low + 1;
    for i in (0..n / 2).rev() {
        sift_down(arr, low, i, n);
    }
    for end in (1..n).rev() {
        arr.swap(low, low + end);
        sift_down(arr, low, 0, end);
    }
}

fn sift_down<T: Ord>(arr: &mut [T], base: usize, start: usize, n: usize) {
    let mut root = start;
    loop {
        let child = 2 * root + 1;
        if child >= n { break; }
        let mut swap_i = root;
        if arr[base + child] > arr[base + swap_i] { swap_i = child; }
        if child + 1 < n && arr[base + child + 1] > arr[base + swap_i] { swap_i = child + 1; }
        if swap_i == root { break; }
        arr.swap(base + root, base + swap_i);
        root = swap_i;
    }
}
